169→/// Validate and return Result (for convenience).
170→///
171→/// # Errors
172→///
173→/// Returns `ConfigValidationError` if any validation rules fail.
174→pub fn validate(config: &BivvyConfig) -> Result<()> {
175→    let errors = validate_config(config);
176→
177→    if errors.is_empty() {
178→        Ok(())
179→    } else {
180→        let messages: Vec<_> = errors.iter().map(|e| e.message.clone()).collect();
181→        Err(BivvyError::ConfigValidationError {
182→            message: messages.join("; "),
183→        })
184→    }
185→}
