  1→//! Variable interpolation for configuration values.
  2→//!
  3→//! Bivvy supports variable interpolation in config values using `${variable}` syntax.
  4→//!
  5→//! # Syntax
  6→//!
  7→//! - `${variable_name}` - replaced with variable value
  8→//! - `$${escaped}` - produces literal `${escaped}` in output
  9→//!
 10→//! # Example
 11→//!
 12→//! ```yaml
 13→//! command: "echo Hello, ${name}!"
 14→//! # With name="World", produces: echo Hello, World!
 15→//! ```
 16→
 17→use crate::error::{BivvyError, Result};
 18→use std::collections::{HashMap, HashSet};
 19→
 20→/// A segment of an interpolated string.
 21→#[derive(Debug, Clone, PartialEq)]
 22→pub enum Segment {
 23→    /// Literal text
 24→    Literal(String),
 25→    /// Variable reference: ${name}
 26→    Variable(String),
 27→}
 28→
 29→/// Parse a string containing ${var} interpolations.
 30→///
 31→/// Supports:
 32→/// - `${variable_name}` - variable interpolation
 33→/// - `$${escaped}` - literal `${escaped}` in output
 34→///
 35→/// # Returns
 36→///
 37→/// Vec of segments representing the parsed string
 38→pub fn parse_interpolation(input: &str) -> Vec<Segment> {
 39→    let mut segments = Vec::new();
 40→    let mut chars = input.chars().peekable();
 41→    let mut current_literal = String::new();
 42→
 43→    while let Some(c) = chars.next() {
 44→        if c == '$' {
 45→            match chars.peek() {
 46→                Some('$') => {
 47→                    // Escaped: $$ becomes $
 48→                    chars.next();
 49→                    if chars.peek() == Some(&'{') {
 50→                        // $${...} -> literal ${...}
 51→                        chars.next(); // consume {
 52→                        current_literal.push('$');
 53→                        current_literal.push('{');
 54→                        // Read until closing brace
 55→                        while let Some(&c) = chars.peek() {
 56→                            chars.next();
 57→                            current_literal.push(c);
 58→                            if c == '}' {
 59→                                break;
 60→                            }
 61→                        }
 62→                    } else {
 63→                        current_literal.push('$');
 64→                    }
 65→                }
 66→                Some('{') => {
 67→                    // Start of variable
 68→                    chars.next(); // consume {
 69→
 70→                    // Flush current literal
 71→                    if !current_literal.is_empty() {
 72→                        segments.push(Segment::Literal(std::mem::take(&mut current_literal)));
 73→                    }
 74→
 75→                    // Read variable name until }
 76→                    let mut var_name = String::new();
 77→                    while let Some(&c) = chars.peek() {
 78→                        if c == '}' {
 79→                            chars.next();
 80→                            break;
 81→                        }
 82→                        var_name.push(chars.next().unwrap());
 83→                    }
 84→
 85→                    segments.push(Segment::Variable(var_name));
 86→                }
 87→                _ => {
 88→                    current_literal.push(c);
 89→                }
 90→            }
 91→        } else {
 92→            current_literal.push(c);
 93→        }
 94→    }
 95→
 96→    // Flush remaining literal
 97→    if !current_literal.is_empty() {
 98→        segments.push(Segment::Literal(current_literal));
 99→    }
100→

  1→//! Config command implementation.
  2→//!
  3→//! The `bivvy config` command shows resolved configuration.
  4→
  5→use std::path::{Path, PathBuf};
  6→
  7→use crate::cli::args::ConfigArgs;
  8→use crate::config::{load_merged_config, ConfigPaths};
  9→use crate::error::{BivvyError, Result};
 10→use crate::ui::{OutputMode, UserInterface};
 11→
 12→use super::dispatcher::{Command, CommandResult};
 13→
 14→/// The config command implementation.
 15→pub struct ConfigCommand {
 16→    project_root: PathBuf,
 17→    args: ConfigArgs,
 18→}
 19→
 20→impl ConfigCommand {
 21→    /// Create a new config command.
 22→    pub fn new(project_root: &Path, args: ConfigArgs) -> Self {
 23→        Self {
 24→            project_root: project_root.to_path_buf(),
 25→            args,
 26→        }
 27→    }
 28→
 29→    /// Get the project root path.
 30→    pub fn project_root(&self) -> &Path {
 31→        &self.project_root
 32→    }
 33→
 34→    /// Get the command arguments.
 35→    pub fn args(&self) -> &ConfigArgs {
 36→        &self.args
 37→    }
 38→}
 39→
 40→impl Command for ConfigCommand {
 41→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 42→        // Load configuration
 43→        let config = match load_merged_config(&self.project_root) {
 44→            Ok(c) => c,
 45→            Err(BivvyError::ConfigNotFound { .. }) => {
 46→                ui.error("No configuration found. Run 'bivvy init' first.");
 47→                return Ok(CommandResult::failure(2));
 48→            }
 49→            Err(e) => return Err(e),
 50→        };
 51→
 52→        // Apply config default_output when no CLI flag was explicitly set
 53→        if ui.output_mode() == OutputMode::Normal {
 54→            ui.set_output_mode(config.settings.default_output.into());
 55→        }
 56→
 57→        // Show config file path(s)
 58→        let paths = ConfigPaths::discover(&self.project_root);
 59→        let existing: Vec<_> = paths.all_existing();
 60→        if !existing.is_empty() {
 61→            for path in &existing {
 62→                ui.message(&format!("# {}", path.display()));
 63→            }
 64→            ui.message("");
 65→        }
 66→
 67→        // Output format
 68→        if self.args.json {
 69→            let json =
 70→                serde_json::to_string_pretty(&config).map_err(|e| BivvyError::Other(e.into()))?;
 71→            ui.message(&json);
 72→        } else {
 73→            let yaml = serde_yaml::to_string(&config).map_err(|e| BivvyError::Other(e.into()))?;
 74→            ui.message(&yaml);
 75→        }
 76→
 77→        Ok(CommandResult::success())
 78→    }
 79→}
