/// Known top-level keys in `BivvyConfig`.
///
/// Any key in a config file that does not appear in this list is rejected
/// with a clear error message, preventing silent fallback to defaults when
/// the file contains typos or invalid structure.
const KNOWN_TOP_LEVEL_KEYS: &[&str] = &[
    "app_name",
    "settings",
    "template_sources",
    "steps",
    "workflows",
    "secrets",
    "extends",
    "requirements",
    "vars",
];

/// Check a raw YAML value for unrecognised top-level keys.
///
/// Returns `ConfigParseError` listing every key that is not in
/// [`KNOWN_TOP_LEVEL_KEYS`]. Null values (empty files) are accepted.
fn check_unknown_keys(value: &serde_yaml::Value, source_path: &Path) -> Result<()> {
    if let Some(mapping) = value.as_mapping() {
        let unknown: Vec<String> = mapping
            .keys()
            .filter_map(|k| k.as_str())
            .filter(|k| !KNOWN_TOP_LEVEL_KEYS.contains(k))
            .map(String::from)
            .collect();

        if !unknown.is_empty() {
            return Err(BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: format!(
                    "unknown configuration key{}: {}",
                    if unknown.len() == 1 { "" } else { "s" },
                    unknown.join(", ")
                ),
            });
        }
    }
    Ok(())
}

/// Load a single config file and parse it into BivvyConfig.
///
/// # Errors
///
/// Returns `ConfigNotFound` if the file doesn't exist.
/// Returns `ConfigParseError` if the YAML is invalid or contains
/// unrecognised keys.
pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
    let content = fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })?;

    parse_config(&content, path)
}

/// Parse YAML content into BivvyConfig.
///
/// Rejects files that contain unrecognised top-level keys so that typos
/// and invalid structure are surfaced instead of silently ignored.
///
/// # Arguments
///
/// * `content` - The YAML content to parse
/// * `source_path` - Path for error reporting
pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    let raw: serde_yaml::Value =
        serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: e.to_string(),
        })?;

    check_unknown_keys(&raw, source_path)?;

    serde_yaml::from_value(raw).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

