            );
        }
    }

    #[test]
    fn parse_config_accepts_all_known_keys() {
        let content = r#"
app_name: Test
settings:
  default_output: verbose
template_sources: []
steps:
  test:
    command: echo test
workflows:
  default:
    steps: [test]
secrets: {}
requirements: {}
vars: {}
"#;
        let result = parse_config(content, Path::new("test.yml"));
        assert!(result.is_ok(), "all known keys should be accepted: {:?}", result);
    }

